def.body:
@mutex.synchronize do
  ensure_open!
  if @running
    raise(BusyError.new(self.class.to_s))
  end
  @session.reset
  @history.clear
end

with_operation do
  old_adapters = @adapters_lora.dup
  old_scales = @adapter_lora_scales.dup
  @adapters_lora.clear
  @adapter_lora_scales.clear

  result = sync_adapters_lora!

  if result != 0
    @adapters_lora.concat(old_adapters)
    @adapter_lora_scales.concat(old_scales)
    raise(Context::Error.new(Llama.format_error("Failed to clear LoRA adapters", result, nil)))
  end

  old_adapters.each do |adapter| adapter.unregister_attachment(self) end
end

@vocab = nil
@grammar_str = nil
@grammar_root = nil
@trigger_patterns = nil
@trigger_tokens = nil
@trigger_pattern_ptrs = nil


super()

types.doc:
Stateful text facade. The canonical transcript is rebuilt before each turn;
this conservative strategy keeps stop-truncated text and native KV state in
agreement until incremental token reconciliation is introduced.

def.body:
@mutex.synchronize do
  ensure_open!
  if @running
    raise(BusyError.new(self.class.to_s))
  end
  @context.memory.clear
  @transcript = ""
end

if @matched
  return ""
end
data = @pending + text
if match = earliest_match(data)
  index, stop = match
  @matched = stop
  @pending = ""
  return (data.byte_slice(0, index)) + (@include_stop ? stop : "")
end

retained = longest_prefix_suffix(data)
safe_size = data.bytesize - retained
@pending = retained == 0 ? "" : data.byte_slice(safe_size, retained)
safe_size == 0 ? "" : data.byte_slice(0, safe_size)
